<section class="form-section"><header><h2><?= esc(lang('DoctorScheduleSettings.reviewedVisits')) ?> · <?= count($report['items']) ?></h2></header><?php if(!$report['items']): ?><p class="settings-information"><?= esc(lang($preview?'DoctorScheduleSettings.previewClean':'DoctorScheduleSettings.noConflicts')) ?></p><?php else: ?><table class="studio-grid impact-table" data-grid-widths="13,19,19,19,20,10"><thead><tr><?php foreach(['visit','date','providers','beforeStatus','afterStatus','review'] as $key): ?><th scope="col"><?= esc($key==='review'?lang('Studio.details'):lang('DoctorScheduleSettings.'.$key)) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($report['items'] as $item):$conflict=empty($item['after_outcome']['compliant']);$id=(int)$item['appointment_id']; ?><tr><td><a class="impact-visit-link" href="<?= $preview&&$conflict?'#impact-resolution-'.$id:base_url('appointment/'.$id) ?>">#<?= $id ?></a><?php if(($item['temporal_state']??'')==='in_progress'): ?><small data-temporal-state="in_progress"><?= esc(lang('DoctorScheduleSettings.inProgressVisit')) ?></small><?php endif; ?><?php if($item['status']==='completed'): ?><small><?= esc(lang('DoctorScheduleSettings.completedPreserved')) ?></small><?php endif; ?></td><td><span dir="ltr"><?= esc($item['appointment_date']) ?></span><small dir="ltr"><?= esc($item['appointment_time'].' – '.$item['end_time']) ?></small><small><?= (int)$item['duration'] ?> <?= esc(lang('DoctorScheduleSettings.minutes')) ?></small></td><td><strong><?= esc($item['provider_name']??$item['chair_name']??'—') ?></strong><?php if($item['provider_user_id']!==null): ?><small dir="ltr">#<?= (int)$item['provider_user_id'] ?></small><?php endif; ?></td><?php foreach(['before_outcome','after_outcome'] as $key): ?><td><span class="impact-status <?= empty($item[$key]['compliant'])?'impact-status--warning':'' ?>"><?= esc(lang(!empty($item[$key]['compliant'])?'DoctorScheduleSettings.compliant':'DoctorScheduleSettings.needsReview')) ?></span><?php if(empty($item[$key]['compliant'])): ?><small><?= esc($item[$key]['localized_reason']??$item[$key]['reason']??'') ?></small><?php endif; ?></td><?php endforeach; ?><td><?php if($preview&&$conflict): ?><a class="button secondary" href="#impact-resolution-<?= $id ?>"><?= esc(lang('Studio.details')) ?></a><?php elseif(!$preview&&$conflict&&isset($retained_exceptions[$id])): ?><a class="button secondary" href="#impact-retained-<?= $id ?>"><?= esc(lang('Studio.details')) ?></a><?php elseif(!empty($item['edit_url'])): ?><a class="button secondary" href="<?= esc($item['edit_url'],'attr') ?>" target="_blank" rel="noopener noreferrer"><?= esc(lang('Studio.editRecord')) ?></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section>
